mapper.select:
SELECT * FROM candidate_application
WHERE 1=1
AND position_id = #{positionId}
AND status = #{status}
AND candidate_name LIKE CONCAT('%', #{candidateName}, '%')
AND candidate_phone LIKE CONCAT('%', #{candidatePhone}, '%')
AND submitted_at >= #{startTime}
AND submitted_at <= #{endTime}
ORDER BY submitted_at DESC
